      10 => ["FX — Clear Screen Effects Only [CE10]", ["map_effects.refresh_rate = 60", "map_effects.set_zoom(100, 20, false)", "map_effects.set_tone(0, 0, 0, 0, 20)", "map_effects.set_color(0, 0, 0, 0, 20)", "map_effects.clear"]]
